"""Retry policy for outbound HTTP calls made through shipclient."""

import re
from datetime import datetime, timezone

_RETRY_STATUSES = {429, 502, 503, 504}
_IDEMPOTENT = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
_NON_IDEMPOTENT = {"POST", "PATCH"}

_DEFAULT = (5, 8.0, 120.0)  # attempts, backoff cap, longest Retry-After
_PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

_MONTHS = {m: i for i, m in enumerate(
    ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"], 1)}
_DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
_DATE_RE = re.compile(
    r"([A-Z][a-z]{2}), (\d{2}) ([A-Z][a-z]{2}) (\d{4}) (\d{2}):(\d{2}):(\d{2}) GMT",
    re.ASCII,
)


def _header(headers, name):
    for k, v in (headers or {}).items():
        if k.lower() == name:
            return v
    return None


def _retry_after(value, now):
    """Wait in seconds from a Retry-After value, or None if absent/malformed."""
    if not isinstance(value, str):
        return None
    value = value.strip()
    if re.fullmatch(r"[0-9]+", value, re.ASCII):
        return float(int(value))
    m = _DATE_RE.fullmatch(value)
    if not m or m.group(3) not in _MONTHS or m.group(1) not in _DAYS:
        return None
    try:
        when = datetime(int(m.group(4)), _MONTHS[m.group(3)], int(m.group(2)),
                        int(m.group(5)), int(m.group(6)), int(m.group(7)),
                        tzinfo=timezone.utc)
    except ValueError:
        return None
    return max(0.0, (when - now).total_seconds())


def retry_delay(
    method: str,
    request_headers: dict[str, str],
    attempt: int,
    status: int | None,
    response_headers: dict[str, str],
    now: datetime,
) -> float | None:
    """Seconds to wait before the next attempt, or None to give up.

    `attempt` is the number of the attempt that just failed, 1 for the first.
    `status` is None when there was no response (a connection error).
    `now` is the current time, timezone-aware UTC.
    """
    if status is not None and status not in _RETRY_STATUSES:
        return None

    m = (method or "").upper()
    if m in _NON_IDEMPOTENT:
        key = _header(request_headers, "idempotency-key")
        if not isinstance(key, str) or not key.strip():
            return None
    elif m not in _IDEMPOTENT:
        return None

    service = _header(request_headers, "x-service")
    max_attempts, cap, max_wait = _PROFILES.get(
        service.strip().lower() if isinstance(service, str) else "", _DEFAULT)

    if attempt >= max_attempts:
        return None

    delay = min(cap, 0.25 * (2 ** (attempt - 1)))

    if status in (429, 503):
        wait = _retry_after(_header(response_headers, "retry-after"), now)
        if wait is not None:
            if wait > max_wait:
                return None
            delay = max(delay, wait)
    return float(delay)
EOF
